F=/scratch/jjyeung/orch_n30/fb_pack
ls $F/camform2/out | tr "\n" " "; echo; head -c 2500 $F/camform2/out/REPORT.md; echo; cat $F/camform2/out/fbp_camform2.tar.sha256; sha256sum $F/camform2/out/*.patch | cut -c1-16,65-
if [ -f $F/camform2/out/fbp_camform2.tar.sha256 ]; then mkdir -p $F/camform2rev/work; cp $F/donorrev/AGENTS.md $F/camform2rev/AGENTS.md; echo  | base64 -d > $F/camform2rev/PROMPT.md; sha256sum $F/camform2rev/PROMPT.md | cut -c1-12
cd $F/camform2rev && tmux new-session -d -s fbp_camform2rev "OMP_NUM_THREADS=8 MKL_NUM_THREADS=8 OPENBLAS_NUM_THREADS=8 nice -n 10 timeout 5400 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes. Write only in this folder.' > $F/camform2rev/cursor.log 2>&1" </dev/null >/dev/null 2>&1; fi
sleep 3; tmux ls | grep fbp | cut -d: -f1 | tr "\n" " "; date -u +%TZ
